function wait(ms) {
  return new Promise((resolve) => setTimeout(() => resolve(ms), ms));
}

wait(100)
  .then((ms) => {
    console.log(`waited ${ms} ms`);
    return "next";                       // becomes the value for the next then
  })
  .then((value) => console.log(value))
  .catch((error) => console.log(error.message))
