const wait = (ms, label) =>
  new Promise((resolve) => setTimeout(() => resolve(label), ms));

async function run() {
  const start = Date.now();
  const results = await Promise.all([wait(300, "A"), wait(100, "B"), wait(200, "C")]);
  console.log(results.join(""));              // input order, not finishing order
  console.log(Date.now() - start < 550);       // about 300 ms in total, not 600

  const settled = await Promise.allSettled([wait(10, "ok"), Promise.reject(new Error("boom"))]);
  console.log(settled.map((r) => r.status).join(", "));

  const fastest = await Promise.race([wait(50, "slow"), wait(10, "fast")]);
  console.log(fastest);
}
run();
